<template><section class="module-view browser-chrome">
  <div class="browser-navigation"><nav class="browser-tabs" aria-label="PCA views"><button v-for="item in ['PCA map','Contributions','Source']" :key="item" :aria-pressed="view===item" @click="view=item"><img :src="tabIcon(item)" alt="" aria-hidden="true"/>{{item}}</button></nav></div>
  <div class="browser-filters"><label class="browser-select">Cell type <BrowserSelect v-model="cell" @change="load" aria-label="Cell type" :options="catalogue.map(item=>item.cellType)"/></label><label v-if="view==='PCA map'" class="browser-select">Color by <BrowserSelect v-model="color" aria-label="Color by" :options="fields"/></label>
    <details v-if="view==='PCA map'"><summary>Plot settings</summary><div class="filter-detail"><label class="browser-select">Hover label <BrowserSelect v-model="label" aria-label="Hover label" :options="fields"/></label><label class="browser-select">X <BrowserSelect v-model="pcx" aria-label="X axis" :options="Array.from({length:10},(_,i)=>({value:i+1,label:'PC'+(i+1)}))"/></label><label class="browser-select">Y <BrowserSelect v-model="pcy" aria-label="Y axis" :options="Array.from({length:10},(_,i)=>({value:i+1,label:'PC'+(i+1)}))"/></label></div></details>
    <label v-if="view==='Contributions'" class="browser-select">Gene contributions <BrowserSelect v-model="pc" aria-label="Gene contributions" :options="Array.from({length:10},(_,i)=>({value:i+1,label:'PC'+(i+1)}))"/></label>
  </div>
  <div class="module-stage" :class="{'is-plot':view==='PCA map'}"><p v-if="error" role="alert">{{error}} <button @click="load">Retry</button></p><p v-else-if="busy" role="status">Loading cell-type PCA…</p>
    <template v-if="data">
      <ScatterPlot v-if="view==='PCA map'" :rows="points" :x-label="`PC${pcx}`" :y-label="`PC${pcy}`" :title="`${cell}-PCA`" :fullscreen="fullscreen" @fullscreen="toggleFullscreen"/>
      <div v-if="view==='Contributions'" class="contribution-view"><p>Top ten genes contributing to variability along PC{{pc}}</p><table><thead><tr><th>Gene</th><th>Contribution (%)</th></tr></thead><tbody><tr v-for="[gene,value] in data.contributions[pc-1]" :key="gene"><td>{{gene}}</td><td><span class="bar" :style="{width:`${value/maxContribution*100}px`}"/>{{value.toPrecision(4)}}</td></tr></tbody></table><div class="table-actions"><button @click="downloadContributions">Download contributions</button><button @click="downloadContributionPlot">Download contribution plot</button></div></div>
      <div v-if="view==='Source'" class="source-panel"><h2>Source &amp; methods</h2><p>Log-normalized pseudobulk PCA scores across ten principal components. Gene contributions are squared loadings, normalized over all genes within each component.</p><a href="https://data.pankbase.org/method/pca_analysismethods" target="_blank" rel="noopener">PCA methods</a><p>Source commit: {{data.source.commit}}</p><div class="table-actions"><button @click="download">Download displayed coordinates</button><button @click="downloadContributions">Download contributions</button></div></div>
    </template>
    <BrowserToolbar v-if="view!=='PCA map'" navigation-only :fullscreen="fullscreen" @fullscreen="toggleFullscreen"/>
  </div>
  <footer class="browser-footer"><div v-if="data && view==='PCA map'" class="legend"><span v-if="numeric">{{color}} ·</span><i v-if="numeric" class="continuous-key" :style="{background:continuousGradient}" aria-hidden="true"/><span v-for="item in legend" :key="item.label"><i :style="{background:item.color}"/>{{item.label}}</span></div><span>{{cell}} · {{data ? data.rows.length : '…'}} pseudobulk samples · PanKbase v3.3</span></footer>
</section></template>
<script>
import { scaleOrdinal, schemeTableau10, scaleSequential, interpolateViridis, extent } from 'd3';
import { localJson, downloadText } from './assets.mjs';
import ScatterPlot from './ScatterPlot.vue';
import BrowserToolbar from './BrowserToolbar.vue';
import browserControls from './browserControls.mjs';
export default {
  components:{ScatterPlot,BrowserToolbar},mixins:[browserControls],props:['context'],data:()=>({view:'PCA map',catalogue:[],cell:'Acinar',data:null,error:'',busy:false,pcx:1,pcy:2,pc:1,color:'Program',label:'Description of diabetes status',serial:0}),
  computed:{fields(){return this.data?.fields||[];},numeric(){return this.data?.numericFields.includes(this.color);},continuousGradient(){return `linear-gradient(to right,${Array.from({length:11},(_,i)=>interpolateViridis(i/10)).join(',')})`;},scale(){return this.numeric?scaleSequential(interpolateViridis).domain(extent(this.data.rows.map(r=>r.attributes[this.color]).filter(Number.isFinite))):scaleOrdinal(schemeTableau10).domain([...new Set(this.data.rows.map(r=>r.attributes[this.color]))].sort());},points(){if(!this.data)return[];return this.data.rows.map(r=>({x:r.scores[this.pcx-1],y:r.scores[this.pcy-1],color:r.attributes[this.color]===null?'#94a3b8':this.scale(r.attributes[this.color]),label:`${this.label}: ${r.attributes[this.label]??'Unknown'}`}));},legend(){if(!this.data)return[];const values=this.scale.domain().filter(v=>v!==null&&v!==undefined);const items=values.map(v=>({label:String(v),color:this.scale(v)}));if(this.data.rows.some(r=>r.attributes[this.color]==null))items.push({label:'Unknown',color:'#94a3b8'});return items;},maxContribution(){return Math.max(...this.data.contributions[this.pc-1].map(r=>r[1]));}},
  async mounted(){await this.load();},
  methods:{downloadContributionPlot(){
    const ns='http://www.w3.org/2000/svg',svg=document.createElementNS(ns,'svg');svg.setAttribute('xmlns',ns);svg.setAttribute('width','720');svg.setAttribute('height','440');svg.setAttribute('viewBox','0 0 720 440');
    const add=(tag,attrs,text)=>{const e=document.createElementNS(ns,tag);Object.entries(attrs).forEach(([k,v])=>e.setAttribute(k,v));if(text!==undefined)e.textContent=text;svg.appendChild(e);};
    add('rect',{width:720,height:440,fill:'white'});add('text',{x:24,y:30,'font-size':18,'font-family':'sans-serif'},`${this.cell} · PC${this.pc} · top gene contributions (%)`);
    this.data.contributions[this.pc-1].forEach(([gene,value],i)=>{const y=62+i*34;add('text',{x:150,y:y+16,'text-anchor':'end','font-family':'sans-serif','font-size':13},gene);add('rect',{x:165,y,width:430*value/this.maxContribution,height:22,fill:'#0f827d'});add('text',{x:605,y:y+16,'font-size':13,'font-family':'sans-serif'},value.toPrecision(5));});
    add('text',{x:24,y:420,'font-size':12,'font-family':'sans-serif'},'PanKbase v3.3 · normalized squared source PCA loadings');downloadText(new XMLSerializer().serializeToString(svg),`${this.cell}-PC${this.pc}-contributions.svg`,'image/svg+xml');
  },async load(){const token=++this.serial;this.error='';this.busy=true;this.data=null;try{if(!this.catalogue.length){this.catalogue=(await localJson('data/manifest.json')).pca;const match=this.catalogue.find(i=>i.cellType.toLowerCase()===this.context.cellType?.toLowerCase());if(match)this.cell=match.cellType;}const item=this.catalogue.find(i=>i.cellType===this.cell);const data=await localJson('data/'+item.asset);if(token===this.serial)this.data=data;}catch(e){if(token===this.serial)this.error=e.message;}finally{if(token===this.serial)this.busy=false;}},download(){downloadText(['PC'+this.pcx+'\tPC'+this.pcy+'\t'+this.color,...this.data.rows.map(r=>[r.scores[this.pcx-1],r.scores[this.pcy-1],r.attributes[this.color]].join('\t'))].join('\n'),`${this.cell}-PCA.tsv`);},downloadContributions(){downloadText(['gene\tcontribution_percent',...this.data.contributions[this.pc-1].map(r=>r.join('\t'))].join('\n'),`${this.cell}-PC${this.pc}-contributions.tsv`);}},
};
</script>
